using System;
using System.Collections.Generic;
using MassiveArmy.Industrial;
using UnityEngine;
using UnityEngine.UIElements;
namespace MassiveArmy.Planetary {
    internal sealed class InventorySlotUi:IDisposable {
        internal sealed class Slot {public InventoryAddress address;public VisualElement surface;}
        readonly PlanetDevelopment world;readonly VisualElement parent,layer;readonly Label ghost,feedback;readonly List<Grid> grids=new List<Grid>();Slot dragging;long dragCount;string dragItem;double nextRefresh,feedbackUntil;
        internal InventorySlotUi(PlanetDevelopment world,VisualElement parent){this.world=world;this.parent=parent;layer=new VisualElement{name="inventory-drag-layer",pickingMode=PickingMode.Ignore};layer.StretchToParentSize();parent.Add(layer);ghost=new Label{pickingMode=PickingMode.Ignore};ghost.style.position=Position.Absolute;ghost.style.backgroundColor=new Color(.07f,.12f,.16f,.96f);ghost.style.color=Color.white;ghost.style.paddingLeft=ghost.style.paddingRight=12;ghost.style.paddingTop=ghost.style.paddingBottom=10;ghost.style.whiteSpace=WhiteSpace.Normal;ghost.style.display=DisplayStyle.None;ghost.style.unityFont=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");layer.Add(ghost);feedback=new Label{pickingMode=PickingMode.Ignore};feedback.style.position=Position.Absolute;feedback.style.left=Length.Percent(25);feedback.style.bottom=100;feedback.style.width=Length.Percent(50);feedback.style.color=Color.white;feedback.style.backgroundColor=new Color(.06f,.1f,.13f,.95f);feedback.style.whiteSpace=WhiteSpace.Normal;feedback.style.display=DisplayStyle.None;layer.Add(feedback);parent.RegisterCallback<PointerMoveEvent>(Move,TrickleDown.TrickleDown);parent.RegisterCallback<PointerUpEvent>(Release,TrickleDown.TrickleDown);}
        internal void Cancel(){dragging=null;ghost.style.display=DisplayStyle.None;if(parent.HasPointerCapture(0))parent.ReleasePointer(0);}
        internal void Tell(string text){world.SurvivalNotice=text;feedback.text=text;feedback.style.display=DisplayStyle.Flex;feedbackUntil=Time.unscaledTimeAsDouble+4;layer.BringToFront();}
        internal static string Name(string item)=>item=="__paydirt"?"Pay dirt":IndustrialCatalog.DisplayItem(item)??"";
        internal static string Mark(string item){string text="";foreach(var word in Name(item).Split(' '))if(word.Length>0)text+=char.ToUpperInvariant(word[0]);return text.Length>3?text.Substring(0,3):text;}
        internal Inventory Read(InventoryAddress address)=>world.IndustrialAuthority?.World.InventoryAt(1,address);
        ItemStack Stack(InventoryAddress address){if(address.section=="reservoir")return null;var inventory=Read(address);return address.slot==-2&&inventory?.bulk.litres>0?new ItemStack("__paydirt",inventory.bulk.litres):inventory?.AtSlot(address.slot);}
        internal void Bind(Button button,InventoryAddress address,VisualElement surface){button.userData=new Slot{address=address,surface=surface};button.RegisterCallback<PointerDownEvent>(e=>{if(e.button!=0&&e.button!=1||world.LocalPlayerDead)return;var stack=Stack(address);if(stack==null)return;dragging=(Slot)button.userData;dragging.surface=world.InventoryWindowSurface??surface;dragCount=e.button==1?(stack.count+1)/2:stack.count;dragItem=stack.item;ghost.text=Name(dragItem)+"\n×"+dragCount;ghost.style.left=e.position.x+14;ghost.style.top=e.position.y+14;ghost.style.display=DisplayStyle.Flex;layer.BringToFront();parent.CapturePointer(e.pointerId);e.StopImmediatePropagation();e.PreventDefault();},TrickleDown.TrickleDown);}
        void Move(PointerMoveEvent e){if(dragging==null)return;ghost.style.left=e.position.x+14;ghost.style.top=e.position.y+14;}
        void Release(PointerUpEvent e){if(dragging==null)return;var source=dragging;var count=dragCount;var item=dragItem;var at=parent.panel?.Pick(e.position);Slot destination=null;bool floor=false;while(at!=null){if(at.userData is Slot slot){destination=slot;break;}if(at.name=="inventory-drop-zone")floor=true;at=at.parent;}if(destination==null&&source.surface!=null&&!source.surface.worldBound.Contains(e.position))floor=true;Cancel();e.StopImmediatePropagation();e.PreventDefault();
            if(destination!=null){var target=destination.address;if(source.address.section==target.section&&source.address.entity==target.entity&&source.address.slot==target.slot){if(target.section=="player"&&target.slot>=0&&target.slot<10)world.PersonalInventory.EquippedSlot=target.slot;return;}var error=world.IndustrialAuthority.MoveInventory(1,source.address,target,count,item);if(error!=null)Tell(error);}
            else if(floor){var error=world.DropInventoryStack(source.address,count,item);Tell(error??"Dropped "+Name(item)+" ×"+count+" · F to recover");}Refresh(true);
        }
        internal Grid AddGrid(VisualElement surface,InventoryAddress address,int start,int count,string label){var grid=new Grid(this,surface,address,start,count,label);grids.Add(grid);return grid;}
        internal void AddDropZone(VisualElement surface){var zone=new Label("DROP ON GROUND\nDrag a stack here, or release it outside the inventory."){name="inventory-drop-zone"};zone.style.height=55;zone.style.marginTop=10;zone.style.paddingTop=8;zone.style.color=new Color(.9f,.63f,.38f);zone.style.backgroundColor=new Color(.13f,.09f,.07f);zone.style.unityTextAlign=TextAnchor.MiddleCenter;zone.style.whiteSpace=WhiteSpace.Normal;surface.Add(zone);}
        internal void Refresh(bool force=false){if(world.LocalPlayerDead){Cancel();return;}if(!force&&Time.unscaledTimeAsDouble<nextRefresh)return;nextRefresh=Time.unscaledTimeAsDouble+.1;for(int i=grids.Count-1;i>=0;i--){if(!parent.Contains(grids[i].Root)){grids.RemoveAt(i);continue;}grids[i].Refresh();}if(feedback.style.display==DisplayStyle.Flex&&Time.unscaledTimeAsDouble>=feedbackUntil)feedback.style.display=DisplayStyle.None;}
        internal sealed class Grid {
            readonly InventorySlotUi ui;readonly InventoryAddress address;readonly int start,minimum;readonly Label title;readonly VisualElement tiles,footer,surface;readonly List<Button> buttons=new List<Button>();int shown=-1,page,lastTotal=-1;public readonly VisualElement Root;
            internal Grid(InventorySlotUi ui,VisualElement surface,InventoryAddress address,int start,int minimum,string label){this.ui=ui;this.surface=surface;this.address=address;this.start=start;this.minimum=minimum;Root=new VisualElement{name="inventory-grid-"+address.section+"-"+address.entity};Root.style.unityFont=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");Root.style.marginBottom=12;surface.Add(Root);title=new Label(label);title.style.color=Color.white;title.style.fontSize=15;title.style.marginBottom=6;Root.Add(title);tiles=new VisualElement();tiles.style.maxWidth=408;tiles.style.flexDirection=FlexDirection.Row;tiles.style.flexWrap=Wrap.Wrap;Root.Add(tiles);footer=new VisualElement();footer.style.flexDirection=FlexDirection.Row;Root.Add(footer);ui.world.IndustrialAuthority.EnsureInventoryLayout(1,address);Refresh();}
            internal void Refresh(){var inventory=ui.Read(address);if(inventory==null){Root.SetEnabled(false);return;}Root.SetEnabled(true);int highest=start+minimum-1;foreach(var stack in inventory.items)if(stack.slot>=start)highest=Math.Max(highest,stack.slot);int total=highest-start+1;int pages=Math.Max(1,(total+59)/60);page=Math.Min(page,pages-1);int offset=start+page*60;int amount=Math.Min(60,total-page*60);
                if(shown!=amount||lastTotal!=total){shown=amount;lastTotal=total;tiles.Clear();buttons.Clear();for(int i=0;i<amount;i++){int index=offset+i;var button=new Button{name="inventory-slot-"+address.section+"-"+address.entity+"-"+index};button.style.width=64;button.style.height=64;button.style.marginLeft=0;button.style.marginTop=0;button.style.marginRight=4;button.style.marginBottom=4;button.style.paddingLeft=button.style.paddingRight=3;button.style.fontSize=11;button.style.whiteSpace=WhiteSpace.Normal;button.style.color=Color.white;button.style.backgroundColor=new Color(.13f,.17f,.19f);button.style.borderTopWidth=button.style.borderRightWidth=button.style.borderLeftWidth=button.style.borderBottomWidth=1;button.style.borderTopColor=button.style.borderRightColor=button.style.borderLeftColor=button.style.borderBottomColor=new Color(.25f,.3f,.32f);tiles.Add(button);buttons.Add(button);ui.Bind(button,new InventoryAddress{entity=address.entity,section=address.section,slot=index},surface);}footer.Clear();if(pages>1){footer.Add(new Button(()=>{page=Math.Max(0,page-1);shown=-1;Refresh();}){text="◀"});footer.Add(new Label("Slots "+(offset+1)+"–"+(offset+amount)+" / "+total));footer.Add(new Button(()=>{page=Math.Min(pages-1,page+1);shown=-1;Refresh();}){text="▶"});}}
                for(int i=0;i<buttons.Count;i++){int index=offset+i;var stack=inventory.AtSlot(index);var button=buttons[i];button.text=stack==null?(address.section=="player"&&index<10?(index==9?"0":(index+1).ToString()):""):Mark(stack.item)+"\n"+Name(stack.item)+"\n×"+stack.count;button.tooltip=stack==null?"Empty slot":Name(stack.item)+" ×"+stack.count+"\nLMB drag stack · RMB drag half";button.style.borderBottomColor=address.section=="player"&&inventory.activeSlot==index?new Color(.12f,.88f,.73f):new Color(.25f,.3f,.32f);}
            }
        }
        internal void AddBulk(VisualElement surface,InventoryAddress address,string title){var button=new Button{name="inventory-bulk-"+address.section+"-"+address.entity};surface.Add(button);address.slot=-2;Bind(button,address,surface);button.style.whiteSpace=WhiteSpace.Normal;button.style.color=Color.white;button.style.backgroundColor=new Color(.15f,.2f,.23f);button.schedule.Execute(()=>{var inventory=Read(address);button.text=title+"\nPAY DIRT  "+(inventory?.bulk.litres??0)+" L · drag to another bulk slot";}).Every(100);}
        internal void AddReservoir(VisualElement surface,long machine){var button=new Button{name="inventory-reservoir-"+machine};button.userData=new Slot{address=new InventoryAddress{entity=machine,section="reservoir"},surface=surface};surface.Add(button);button.schedule.Execute(()=>button.text="WATER RESERVOIR  "+(world.IndustrialAuthority.World.Machine(machine)?.water??0)+" / 10,000 L\nDrop clean water here").Every(100);button.style.whiteSpace=WhiteSpace.Normal;}
        public void Dispose(){Cancel();parent.UnregisterCallback<PointerMoveEvent>(Move,TrickleDown.TrickleDown);parent.UnregisterCallback<PointerUpEvent>(Release,TrickleDown.TrickleDown);layer.RemoveFromHierarchy();}
    }
}



